}
selector #gallery-2{
    display:flex;
    flex-direction: row;
    flex-wrap: wrap;
    justify-content: center;
}

}

@media (max-width: 479px) {

selector .elementor-image-gallery .gallery.gallery-columns-5 .gallery-item{
    max-width: 33%;
}

